package com.ecole.gestion_scolaire.hr.controller; import com.ecole.gestion_scolaire.hr.dto.*; import com.ecole.gestion_scolaire.hr.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/hr/compensation") public class CompensationController { private final CompensationService service; public CompensationController(CompensationService s){service=s;} @PostMapping("/plans") @PreAuthorize("hasAuthority('REMUNERATION_GERER')") public ResponseEntity<CompensationPlanResponse> plan(@Valid @RequestBody CompensationPlanRequest q){return ResponseEntity.status(201).body(service.createPlan(q));} @GetMapping("/plans/employee/{id}") @PreAuthorize("hasAuthority('REMUNERATION_CONSULTER')") public List<CompensationPlanResponse> plans(@PathVariable Long id){return service.plans(id);} @PostMapping("/teacher-rates") @PreAuthorize("hasAuthority('REMUNERATION_GERER')") public ResponseEntity<TeacherRateResponse> rate(@Valid @RequestBody TeacherRateRequest q){return ResponseEntity.status(201).body(service.createRate(q));} @GetMapping("/teacher-rates/teacher/{id}") @PreAuthorize("hasAuthority('REMUNERATION_CONSULTER')") public List<TeacherRateResponse> rates(@PathVariable Long id){return service.rates(id);} }